commands:
pwsh -NoProfile -Command '
$files = @("./api/_lib/pantry-store.ps1","./api/_lib/pantry-render.ps1","./podex.ps1")
foreach ($f in $files) {
  $errs = $null
  [void][System.Management.Automation.Language.Parser]::ParseFile((Resolve-Path $f), [ref]$null, [ref]$errs)
  if ($errs) { Write-Host "FAIL $f"; $errs | ForEach-Object { Write-Host $_ } } else { Write-Host "OK   $f" }
}'

cd <WORKSPACE>/pantry
pwsh -NoProfile -Command '
foreach ($f in @("./api/_lib/pantry-store.ps1","./api/_lib/pantry-render.ps1","./podex.ps1")) {
  $r = Invoke-ScriptAnalyzer -Path $f -Severity Warning,Error
  if (-not $r) { Write-Host "OK   $f" } else { Write-Host "WARN $f"; $r | Select-Object Line,RuleName,Message | Format-Table -AutoSize | Out-String | Write-Host }
}'
